CREATE TYPE "InventoryMovementType" AS ENUM ('OPENING_BALANCE', 'PURCHASE_RECEIVED', 'SALE', 'DAMAGED', 'EXPIRED', 'CORRECTION', 'RETURN');
CREATE TABLE "Branch" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NOT NULL, "isDefault" BOOLEAN NOT NULL DEFAULT false, "address" TEXT, "phone" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Branch_pkey" PRIMARY KEY ("id"));
CREATE TABLE "StaffMember" ("id" TEXT NOT NULL, "clerkUserId" TEXT NOT NULL, "branchId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "StaffMember_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Supplier" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "contactName" TEXT, "phone" TEXT, "email" TEXT, "address" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Supplier_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InventoryMovement" ("id" TEXT NOT NULL, "branchId" TEXT NOT NULL, "medicineId" TEXT NOT NULL, "type" "InventoryMovementType" NOT NULL, "quantity" INTEGER NOT NULL, "reason" TEXT NOT NULL, "referenceId" TEXT, "actorId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "InventoryMovement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL, "branchId" TEXT NOT NULL, "actorId" TEXT, "action" TEXT NOT NULL, "entityType" TEXT NOT NULL, "entityId" TEXT NOT NULL, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));
INSERT INTO "Branch" ("id", "name", "code", "isDefault", "updatedAt") VALUES ('default-branch', 'Main Branch', 'MAIN', true, CURRENT_TIMESTAMP);
ALTER TABLE "Medicine" ADD COLUMN "branchId" TEXT; ALTER TABLE "Medicine" ADD COLUMN "supplierId" TEXT; ALTER TABLE "Medicine" ADD COLUMN "reorderLevel" INTEGER NOT NULL DEFAULT 20; ALTER TABLE "Sale" ADD COLUMN "branchId" TEXT;
UPDATE "Medicine" SET "branchId" = 'default-branch'; UPDATE "Sale" SET "branchId" = 'default-branch';
WITH duplicates AS (SELECT "id", ROW_NUMBER() OVER (PARTITION BY "name", "batchNumber", "branchId" ORDER BY "id") AS number FROM "Medicine") UPDATE "Medicine" m SET "batchNumber" = m."batchNumber" || '-legacy-' || RIGHT(m."id", 6) FROM duplicates d WHERE m."id" = d."id" AND d.number > 1;
ALTER TABLE "Medicine" ALTER COLUMN "price" TYPE DECIMAL(12,2) USING ROUND("price"::numeric, 2); ALTER TABLE "Medicine" ALTER COLUMN "costPrice" TYPE DECIMAL(12,2) USING ROUND("costPrice"::numeric, 2); ALTER TABLE "Sale" ALTER COLUMN "totalAmount" TYPE DECIMAL(12,2) USING ROUND("totalAmount"::numeric, 2); ALTER TABLE "SaleItem" ALTER COLUMN "unitPrice" TYPE DECIMAL(12,2) USING ROUND("unitPrice"::numeric, 2); ALTER TABLE "SaleItem" ALTER COLUMN "total" TYPE DECIMAL(12,2) USING ROUND("total"::numeric, 2);
INSERT INTO "StaffMember" ("id", "clerkUserId", "branchId", "updatedAt") SELECT 'legacy-staff-' || "cashierId", "cashierId", 'default-branch', CURRENT_TIMESTAMP FROM "Sale" GROUP BY "cashierId";
ALTER TABLE "Medicine" ALTER COLUMN "branchId" SET NOT NULL; ALTER TABLE "Sale" ALTER COLUMN "branchId" SET NOT NULL;
CREATE UNIQUE INDEX "Branch_code_key" ON "Branch"("code"); CREATE UNIQUE INDEX "StaffMember_clerkUserId_key" ON "StaffMember"("clerkUserId"); CREATE UNIQUE INDEX "Medicine_name_batchNumber_branchId_key" ON "Medicine"("name", "batchNumber", "branchId"); CREATE INDEX "Medicine_branchId_name_idx" ON "Medicine"("branchId", "name"); CREATE INDEX "Medicine_branchId_expiryDate_idx" ON "Medicine"("branchId", "expiryDate"); CREATE INDEX "Medicine_branchId_stockQuantity_idx" ON "Medicine"("branchId", "stockQuantity"); CREATE INDEX "Medicine_supplierId_idx" ON "Medicine"("supplierId"); CREATE INDEX "Sale_branchId_createdAt_idx" ON "Sale"("branchId", "createdAt"); CREATE INDEX "Sale_cashierId_idx" ON "Sale"("cashierId"); CREATE INDEX "SaleItem_medicineId_idx" ON "SaleItem"("medicineId"); CREATE INDEX "StaffMember_branchId_idx" ON "StaffMember"("branchId"); CREATE INDEX "Supplier_name_idx" ON "Supplier"("name"); CREATE INDEX "InventoryMovement_branchId_createdAt_idx" ON "InventoryMovement"("branchId", "createdAt"); CREATE INDEX "InventoryMovement_medicineId_createdAt_idx" ON "InventoryMovement"("medicineId", "createdAt"); CREATE INDEX "InventoryMovement_referenceId_idx" ON "InventoryMovement"("referenceId"); CREATE INDEX "AuditLog_branchId_createdAt_idx" ON "AuditLog"("branchId", "createdAt"); CREATE INDEX "AuditLog_entityType_entityId_idx" ON "AuditLog"("entityType", "entityId");
ALTER TABLE "Medicine" ADD CONSTRAINT "Medicine_branchId_fkey" FOREIGN KEY ("branchId") REFERENCES "Branch"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Medicine" ADD CONSTRAINT "Medicine_supplierId_fkey" FOREIGN KEY ("supplierId") REFERENCES "Supplier"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "Sale" ADD CONSTRAINT "Sale_branchId_fkey" FOREIGN KEY ("branchId") REFERENCES "Branch"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Sale" ADD CONSTRAINT "Sale_cashierId_fkey" FOREIGN KEY ("cashierId") REFERENCES "StaffMember"("clerkUserId") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "StaffMember" ADD CONSTRAINT "StaffMember_branchId_fkey" FOREIGN KEY ("branchId") REFERENCES "Branch"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "InventoryMovement" ADD CONSTRAINT "InventoryMovement_branchId_fkey" FOREIGN KEY ("branchId") REFERENCES "Branch"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "InventoryMovement" ADD CONSTRAINT "InventoryMovement_medicineId_fkey" FOREIGN KEY ("medicineId") REFERENCES "Medicine"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_branchId_fkey" FOREIGN KEY ("branchId") REFERENCES "Branch"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
INSERT INTO "InventoryMovement" ("id", "branchId", "medicineId", "type", "quantity", "reason") SELECT 'opening-' || "id", "branchId", "id", 'OPENING_BALANCE', "stockQuantity", 'Opening balance recorded by Phase 1 migration' FROM "Medicine";
